    const oldLang=this.lang;this.lang=languageCode(value?.language);
    if(previous?.user?.id!==value?.user?.id){this.dashboards=[];this.sidebarDashboards=[];this._activeDashboardKey=null;this._proposal=null;this._data=null;this._detail=null;this.revealed.clear();}
